use std::fs

struct Tree {
    keys: Vec<int>,
    left: Vec<int>,
    right: Vec<int>,
    root: int,
}

impl Tree {
    fn contains(self, x: int) -> bool {
        let mut n = self.root
        while n >= 0 {
            let k = self.keys[n as usize]
            if x == k { return true }
            if x < k { n = self.left[n as usize] } else { n = self.right[n as usize] }
        }
        false
    }

    fn insert(self, x: int) {
        let id = self.keys.len() as int
        self.keys.push(x)
        self.left.push(-1)
        self.right.push(-1)
        if self.root < 0 {
            self.root = id
            return
        }
        let mut n = self.root
        loop {
            let k = self.keys[n as usize]
            if x < k {
                if self.left[n as usize] < 0 {
                    self.left[n as usize] = id
                    return
                }
                n = self.left[n as usize]
            } else {
                if self.right[n as usize] < 0 {
                    self.right[n as usize] = id
                    return
                }
                n = self.right[n as usize]
            }
        }
    }

    fn del(self, n: int, x: int) -> int {
        if n < 0 { return -1 }
        let k = self.keys[n as usize]
        if x < k {
            let l = self.del(self.left[n as usize], x)
            self.left[n as usize] = l
            return n
        }
        if x > k {
            let r = self.del(self.right[n as usize], x)
            self.right[n as usize] = r
            return n
        }
        if self.left[n as usize] < 0 { return self.right[n as usize] }
        if self.right[n as usize] < 0 { return self.left[n as usize] }
        let mut s = self.right[n as usize]
        while self.left[s as usize] >= 0 { s = self.left[s as usize] }
        let sk = self.keys[s as usize]
        self.keys[n as usize] = sk
        let r = self.del(self.right[n as usize], sk)
        self.right[n as usize] = r
        n
    }

    fn walk(self, n: int, out: Vec<string>) -> Vec<string> {
        if n < 0 { return out }
        let mut o = self.walk(self.left[n as usize], out)
        o.push("${self.keys[n as usize]}")
        self.walk(self.right[n as usize], o)
    }

    fn height(self, n: int) -> int {
        if n < 0 { return 0 }
        let a = self.height(self.left[n as usize])
        let b = self.height(self.right[n as usize])
        if a > b { a + 1 } else { b + 1 }
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], left: [], right: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").collect()
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) { println("dup") } else {
                t.insert(x)
                println("ok")
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) {
                t.root = t.del(t.root, x)
                println("ok")
            } else { println("missing") }
        } else if cmd == "inorder" {
            if t.root < 0 { println("<empty>") } else {
                let o = t.walk(t.root, [])
                println(o.join(" "))
            }
        } else if cmd == "height" {
            println("${t.height(t.root)}")
        } else if cmd == "min" {
            if t.root < 0 { println("empty") } else {
                let mut n = t.root
                while t.left[n as usize] >= 0 { n = t.left[n as usize] }
                println("${t.keys[n as usize]}")
            }
        } else if cmd == "max" {
            if t.root < 0 { println("empty") } else {
                let mut n = t.root
                while t.right[n as usize] >= 0 { n = t.right[n as usize] }
                println("${t.keys[n as usize]}")
            }
        }
    }
}

